{id: "canvas_Row1", smiles: "CC1C(=O)CCC2C1(C)CCC1C2(C)CC2OC(=O)C13CCC1(C)CCC(C)(C)CC1C23C" },
{id: "canvas_Row2", smiles: "CC(=O)O[C@@H]1CC[C@H]2[C@]3(C)C[C@H]4OC(=O)[C@@]5(CC[C@@]6(C)CCC(C)(C)C[C@@H]6[C@]45C)[C@H]3CC[C@]2(C)[C@H]1C" },
{id: "canvas_Row3", smiles: "CC1C(O)CCC2C1(C)CCC1C2(C)CCC2(C)C3CC(C)(C)CCC3(C)CCC12C(=O)O" },
{id: "canvas_Row4", smiles: "O=C(O)CCCC/C=C/CCCCCC[C@H]1C=CCC1" }
    ];
    const drawer = new SmilesDrawer.Drawer({ width: 150, height: 150 });
